cat /app/resources/treasury_bulletin_1970_01.json | python3 -c "
import json,sys
data = json.load(sys.stdin)
tables = [e for e in data['document']['elements'] if e.get('type')=='table']
for i, t in enumerate(tables[:10]):
    print(f'Table {i}:')
    if t.get('content'):
        print(t['content'][:500])
    if t.get('rows'):
        rows = t['rows']
        if rows:
            print('First row:', rows[0][:5] if isinstance(rows[0], list) else rows[0])
"
